def decode(b):
    for p in ('gtin:','upc:','ean:'):
        if b.startswith(p):
            b=b[len(p):];break
    out='';i=0
    while i<len(b):
        if b[i]=='\\' and i+1<len(b):i+=1
        out+=b[i];i+=1
    return out
def load(path,required):
